// The Gmail trigger with `simple` on hands over a flat message. Which field
// carries the body depends on whether the newsletter sent text, HTML or both,
// so all three are tried rather than assuming one.
//
// single-item input: the trigger fires once per message.
//
// Settings sits between the trigger and this node and a Set node replaces the
// item, so $input here would be the config. The message is read by name.
const j = $('Watch The Funding Label').first().json || {};

let body = String(j.text || j.textPlain || '');
if (!body.trim()) {
  body = String(j.html || j.textHtml || '')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<[^>]+>/g, ' ');
}
if (!body.trim()) { body = String(j.snippet || ''); }

const text = body
  .replace(/https?:\/\/\S+/g, ' ')     // tracking links are most of a newsletter by weight
  .replace(/&[a-z]+;/gi, ' ')
  .replace(/[ \t]+/g, ' ')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

if (text.length < 200) {
  throw new Error('That message had almost no body text (' + text.length + ' chars). Check the label is on the newsletter itself and not on a notification about it.');
}

return [{ json: {
  subject: String(j.subject || j.Subject || '(no subject)'),
  from: String(j.from || j.From || ''),
  received: String(j.date || j.internalDate || ''),
  text: text.slice(0, 12000),
}}];

