// The extractor nests its answer under `output`. Reading j.companies instead
// of j.output.companies returns undefined on a run where every node is green,
// which reads as a quiet newsletter rather than a bug.
const cfg = $('Settings').first().json;
const raw = $('Pull Out The Rounds').first().json;
const payload = (raw && raw.output) || raw || {};
const found = Array.isArray(payload.companies) ? payload.companies : [];

// Anything already in the table was enriched on a previous issue. Dropping it
// here rather than after the lookup is what makes covering the same round in
// three newsletters cost nothing the second and third time.
const seen = new Set(
  $input.all()
    .map(function (i) { return String((i.json || {}).company_key || '').toLowerCase(); })
    .filter(Boolean)
);

// The model returns the stage as "Series A", "series-a" and "A" across runs, so
// it is normalised before anything sorts or counts by it.
function stage(v) {
  const s = String(v || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  if (/pre seed/.test(s)) { return 'Pre-seed'; }
  if (/seed/.test(s)) { return 'Seed'; }
  const m = s.match(/series ([a-z])/) || s.match(/^([a-z])$/);
  if (m) { return 'Series ' + m[1].toUpperCase(); }
  if (/growth|late|private equity|pe /.test(s)) { return 'Growth'; }
  return 'Unknown';
}

const floor = Math.max(0, Number(cfg.min_round_musd) || 0);
const cap = Math.max(1, Math.min(20, Number(cfg.max_companies) || 6));

const fresh = [];
for (const c of found) {
  const name = String((c && c.name) || '').trim();
  if (!name) { continue; }
  const key = name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
  if (!key || seen.has(key)) { continue; }
  seen.add(key);

  const amount = Number(String((c && c.amount_musd) || '').replace(/[^0-9.]/g, '')) || 0;
  if (floor && amount && amount < floor) { continue; }

  fresh.push({
    company_key: key,
    company: name,
    amount_musd: amount,
    stage: stage(c && c.stage),
    investors: String((c && c.investors) || '').slice(0, 200),
    what_they_do: String((c && c.what_they_do) || '').slice(0, 300),
    source_subject: $('Read The Email').first().json.subject,
  });
}

fresh.sort(function (a, b) { return b.amount_musd - a.amount_musd; });
const chosen = fresh.slice(0, cap);

// A filter that can return zero items ends the branch, and the quiet path below
// it would never fire. One marker item always comes back.
if (!chosen.length) {
  return [{ json: { has_new: false, found: found.length, company: '' } }];
}
return chosen.map(function (c) {
  return { json: Object.assign({ has_new: true, found: found.length }, c) };
});

// The top results for a newly funded company are news stories about the round,
// not the company. Measured on this exact search: the first non-publisher host
// for "Pennylane funding round" was cnbc.com, so a blocklist alone picks a news
// site and calls it a home page.
//
// So the host is matched against the company name first, and the blocklist is
// only there to decide which results count as press coverage.
const PUBLISHERS = [
  'techcrunch.', 'crunchbase.', 'linkedin.', 'bloomberg.', 'reuters.', 'forbes.',
  'businesswire.', 'prnewswire.', 'globenewswire.', 'axios.', 'sifted.', 'eu-startups.',
  'finsmes.', 'venturebeat.', 'pitchbook.', 'tracxn.', 'wikipedia.', 'youtube.',
  'facebook.', 'x.com', 'twitter.', 'medium.com', 'substack.com', 'prweb.', 'cnbc.',
  'ft.com', 'wsj.com', 'businessinsider.', 'fortune.com', 'sifted.eu', 'yahoo.',
];

function unwrapSerp(x) {
  // `format: json` returns the whole HTTP envelope with the parsed SERP nested
  // in `body` as a STRING. Reading `organic` off the top level finds nothing,
  // which reads as a company with no web presence rather than as a parse miss.
  let p = x;
  if (p && p.body != null) { p = p.body; }
  if (typeof p === 'string') {
    try { p = JSON.parse(p); } catch (e) { p = {}; }
  } else if (p && typeof p.data === 'string') {
    try { p = JSON.parse(p.data); } catch (e) { p = {}; }
  } else if (p && p.data && typeof p.data === 'object') {
    p = p.data;
  }
  return p || {};
}

const body = unwrapSerp($input.item.json);
if (body.error) {
  throw new Error('Bright Data refused the search: ' + JSON.stringify(body.error).slice(0, 300));
}

const org = body.organic || [];
const company = $('Pick The New Ones').item.json;
const slug = String(company.company || '').toLowerCase().replace(/[^a-z0-9]/g, '');

let site = '';
const evidence = [];

for (const r of org) {
  const link = String((r && r.link) || '');
  if (!link) { continue; }
  const host = link.replace(/^https?:\/\//, '').split('/')[0].toLowerCase();
  // Google occasionally returns its own redirect wrapper in place of a
  // publisher. It is not a page and cannot be fetched.
  if (host.indexOf('google.') === 0) { continue; }

  const isPress = PUBLISHERS.some(function (d) { return host.indexOf(d) >= 0; });
  if (isPress) {
    evidence.push(String((r && r.description) || '').slice(0, 240));
    continue;
  }

  // The registrable name, without www and without the suffix: northbeam.io
  // and www.pennylane.tech both reduce to one word to compare against.
  const parts = host.replace(/^www\./, '').split('.');
  const label = parts[0] || '';
  if (!site && slug && label && (label.indexOf(slug) >= 0 || slug.indexOf(label) >= 0)) {
    site = 'https://' + host + '/';
  }
}

return { json: Object.assign({}, company, {
  site: site,
  // Empty is an honest answer. Falling back to "the first thing that was not a
  // newspaper" is how cnbc.com ends up being read as a company home page.
  coverage: evidence.slice(0, 5).join(' | '),
})};

// The Unlocker replies as text, so the body arrives as a string on some
// responses and under `data` on others depending on how the zone answered.
//
// A zero-length body is a fetch that failed, not a company with nothing to say,
// so it is recorded as absent rather than passed on as an empty page - the
// model would otherwise score a blank as a bad fit.
//
// Runs once for each item, one page per company.
const raw = $input.item.json;
const company = $('Find Their Site').item.json;

const body = String(typeof raw === 'string' ? raw : ((raw && (raw.data || raw.body)) || ''));
const page = body
  .replace(/!\[[^\]]*\]\([^)]*\)/g, ' ')   // images carry no argument
  .replace(/\s+/g, ' ')
  .trim();

return { json: Object.assign({}, company, {
  homepage: page ? page.slice(0, 4000) : '(their home page did not come back)',
  page_chars: page.length,
})};

