THEIR OWN HOME PAGE:
{{ $json.homepage }}

Answer with JSON and nothing else, in this exact shape:
{"score": 0, "tier": "hot", "what_they_do": "", "why_now": "", "angle": ""}

score: 0-100, how well they match WHO WE SELL TO. Be strict; most companies are not a fit.
tier: "hot" above 70, "watch" between 40 and 70, "pass" below 40.
what_they_do: one line, in your own words, from their home page rather than the newsletter.
why_now: one line on what the money changes for them. If nothing in the evidence supports a reason, write "no specific trigger".
angle: one sentence a rep could open with. Reference something specific from the evidence, not a generic congratulation.

parameters.jsCode:
// The model ignores the enum often enough to plan for - "Hot", "HOT" and
// "high" have all come back where "hot" was asked for - so the tier is derived
// from the score and the returned label is only a tie-breaker.
//
// Runs once for each item: the chain answers once per company.
const cfg = $('Settings').first().json;
const item = $('Find Their Site').item.json;
const raw = String(($input.item.json || {}).text || '');

let parsed = {};
const start = raw.indexOf('{');
const end = raw.lastIndexOf('}');
if (start >= 0 && end > start) {
  try { parsed = JSON.parse(raw.slice(start, end + 1)); } catch (e) { parsed = {}; }
}

const hot = Math.max(1, Math.min(100, Number(cfg.hot_score) || 70));
const watch = Math.max(1, Math.min(hot - 1, Number(cfg.watch_score) || 40));

let score = Number(parsed.score);
if (!isFinite(score)) { score = 0; }
score = Math.max(0, Math.min(100, Math.round(score)));

const tier = score >= hot ? 'hot' : score >= watch ? 'watch' : 'pass';

return { json: Object.assign({}, item, {
  score: score,
  tier: tier,
  what_they_do: String(parsed.what_they_do || item.what_they_do || '').slice(0, 300),
  why_now: String(parsed.why_now || '').slice(0, 300),
  angle: String(parsed.angle || '').slice(0, 400),
  first_seen: new Date().toISOString().slice(0, 10),
})};

// The upsert emits one item per hot company. Without executeOnce the digest
// would be assembled once per company and Gmail would send it N times.
//
// single-item input: this reads the whole run back by name rather than
// rebuilding it from the one item currently in flight.
const cfg = $('Settings').first().json;
const all = $('Read The Verdict').all().map(function (i) { return i.json; });
const hot = all.filter(function (c) { return c.tier === 'hot'; });
const watching = all.filter(function (c) { return c.tier === 'watch'; });

hot.sort(function (a, b) { return b.score - a.score; });

const blocks = hot.map(function (c) {
  return [
    '<h3 style="margin:18px 0 4px">' + c.company + ' - ' + c.stage + ', $' + c.amount_musd + 'M <span style="color:#888;font-weight:normal">(' + c.score + '/100)</span></h3>',
    '<p style="margin:2px 0"><em>' + c.what_they_do + '</em></p>',
    '<p style="margin:2px 0"><strong>Why now:</strong> ' + c.why_now + '</p>',
    '<p style="margin:2px 0"><strong>Opening line:</strong> ' + c.angle + '</p>',
    c.site ? '<p style="margin:2px 0"><a href="' + c.site + '">' + c.site + '</a></p>' : '',
  ].join('');
});

const html = [
  '<p>From <em>' + (all[0] ? all[0].source_subject : 'your funding label') + '</em>: ' + hot.length + ' worth a call, ' + watching.length + ' on the watch list.</p>',
  blocks.join(''),
  watching.length ? '<p style="color:#666">Watching: ' + watching.map(function (c) { return c.company + ' (' + c.score + ')'; }).join(', ') + '</p>' : '',
].join('');

return [{ json: {
  to: cfg.digest_to,
  subject: hot.length + ' newly funded companies worth a call',
  html: html,
  hot: hot.length,
}}];
